referenceSolutions.javascript:
export function reverseNodesInKGroup(values          , k        )           {
const out         =[];for(let i=0;i<values.length;i+=k){const group=values.slice(i,i+k);out.push(...(group.length===k?group.reverse():group));}return out;
}

